### Patterns to Follow
The fused method should keep the same `Totals` accumulator and the same error variants. The structure is:

```rust
fn build_contiguous_prefix(&self) -> Result<Option<PendingPrefixCheckpoint>, PrefixCheckpointError> {
    let first_sequence_no = self.next_sequence_no;
    let mut expected = first_sequence_no;
    let mut previous_key: Option<&ItemKey> = self.last_checkpoint_key.as_ref();
    let mut totals = Totals::default();
    let mut last_sequence_no = None;
    let mut last_boundary = None;

    for (&sequence_no, receipt) in self.receipts.range(expected..) {
        if sequence_no != expected { break; }
        // monotonicity check ...
        // totals.accumulate(...) ...
        last_sequence_no = Some(sequence_no);
        last_boundary = Some(receipt.completed_unit().checkpoint_boundary());
        expected = expected.checked_add(1).unwrap_or(u64::MAX); // or break
    }

    let Some(last_seq) = last_sequence_no else { return Ok(None); };
    // construct PendingPrefixCheckpoint from last_boundary, totals, etc.
}
```

